sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float zoom;
uniform float2 center;
uniform float adaptive;
uniform float style;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float s = clamp(zoom, 0.0, 2.5);
    float2 lo = screen.xy + 0.5;
    float2 hi = screen.xy + screen.zw - 0.5;
    float4 sum = float4(0.0);
    if (style > 0.5) {
        float r = length(d);
        float2 u = r > 0.001 ? d / r : float2(0.0);
        float span = 0.68 * s * max(size.x, size.y);
        if (adaptive > 0.5) {
            float2 e = u * span * length(d / size);
            for (int i = 0; i < 64; ++i) {
                sum += float4(image.eval(clamp(coord + e * (float(i) / 63.0 - 0.5), lo, hi)));
            }
            return half4(sum / 64.0);
        }
        for (int i = 0; i < 128; ++i) {
            sum += float4(image.eval(clamp(coord + u * span * (float(i) / 127.0 - 0.5), lo, hi)));
        }
        return half4(sum / 128.0);
    }
    if (adaptive > 0.5) {
        for (int i = 0; i < 64; ++i) {
            float t = 0.8 * s * (float(i) / 63.0 - 0.5);
            sum += float4(image.eval(clamp(c + d * (1.0 + t), lo, hi)));
        }
        return half4(sum / 64.0);
    }
    float2 e = d * (4.0 * sqrt(size.x * size.y) / max(length(d), 0.001));
    for (int i = 0; i < 128; ++i) {
        float t = s * (float(i) / 127.0 - 0.5);
        sum += float4(image.eval(clamp(coord + e * t, lo, hi)));
    }
    return half4(sum / 128.0);
}
